head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.test = function(id) {
	var tabOpt = {
		label: id,
		closable: true,
		openAction: "select"
	};
	var contOpt = {
		frameMode: "iframe",
		src: "/sample/common_link/tabControl_spaInitCount_WPF-1854_(WSQ-2955)_sub.xml"
	};
	var newTabID = tabControl1.addTab(id, tabOpt, contOpt);
};
scwin.trigger1_onclick = function(e) {
	scwin.test("test1");
};
scwin.trigger2_onclick = function(e) {
	scwin.test("test2");
};
scwin.isEleInEle = function(el1Id, el2Id) {
	var el = scwin.__getDom(el1Id).firstElementChild;
	return el.id == $p.id + el2Id;
};
scwin.isEleInEle1 = function(el1Id, el2Id) {
	var el = scwin.__getDom(el1Id).lastElementChild;
	return el.id == $p.id + el2Id;
};
scwin.isEleClosed = function(id) {
	var el = scwin.__getDom(id);
	return el.style.display == "none";
};
scwin.hasErrlog = function() {
	return WebSquare.logger.getErrorLog();
};
scwin.checktype = function() {
	return typeof tabControl1_contents_test2 === 'undefined';
};
